var getConnInfo=e=>{const t=e.env.requestContext;let n;if("identity"in t&&t.identity?.sourceIp)n=t.identity.sourceIp;else if("http"in t&&t.http?.sourceIp)n=t.http.sourceIp;else{const t=e.req.header("x-forwarded-for");if(t){const e=t.split(",");n=e[e.length-1].trim()}}return{remote:{address:n}}};export{getConnInfo};